OPERATOR_ATTRIBUTES:
{
  "expressions": [
    "number of rows deleted",
    "number of rows inserted"
  ]
}

{
  "filter_condition": "(IFF((IFF(1 >= (ABS(SUM(METADATA$ACTION))), SUM(METADATA$ACTION), TO_NUMBER(RAISE_USER_ERROR('XX000', TO_NUMBER('091973', 18, 0), 'Internal Stream/CHANGES query error for ROW_ID: ''%1%''.', REGEXP_REPLACE(METADATA$ROW_ID, '~.{0,20}:([A-Za-z0-9+\\\\/=]{20,})', '~[OBFVAL]:\\\\1', 1, 0, 'c')), 18, 5))) > (0), 'INSERT', 'DELETE')) = 'DELETE'"
}

{
  "filter_condition": "(ANY_VALUE_WITHOUT_NULLS_INTRODUCED(UNION_ALL(T_INSERT_METADATA_ONLY.METADATA$PARTITION_NAME, T_DELETE_METADATA_ONLY.METADATA$PARTITION_NAME)) IS NOT NULL) AND (ANY_VALUE_WITHOUT_NULLS_INTRODUCED(UNION_ALL(T_INSERT_METADATA_ONLY.METADATA$PARTITION_ROW_NUMBER, T_DELETE_METADATA_ONLY.METADATA$PARTITION_ROW_NUMBER)) IS NOT NULL) AND ((IFF(1 >= (ABS(SUM(METADATA$ACTION))), SUM(METADATA$ACTION), TO_NUMBER(RAISE_USER_ERROR('XX000', TO_NUMBER('091973', 18, 0), 'Internal Stream/CHANGES query error for ROW_ID: ''%1%''.', REGEXP_REPLACE(ANY_VALUE_WITHOUT_NULLS_INTRODUCED(UNION_ALL(METADATA$ROW_ID, METADATA$ROW_ID)), '~.{0,20}:([A-Za-z0-9+\\\\/=]{20,})', '~[OBFVAL]:\\\\1', 1, 0, 'c')), 18, 5))) <> (0))"
}

{
  "filter_condition": "(T_INSERT.METADATA$PARTITION_NAME IS NOT NULL) AND (T_INSERT.METADATA$PARTITION_ROW_NUMBER IS NOT NULL)"
}

{
  "filter_condition": "(T_DELETE.METADATA$PARTITION_NAME IS NOT NULL) AND (T_DELETE.METADATA$PARTITION_ROW_NUMBER IS NOT NULL)"
}

{
  "filter_condition": "(IFF((IFF(1 >= (ABS(SUM(METADATA$ACTION))), SUM(METADATA$ACTION), TO_NUMBER(RAISE_USER_ERROR('XX000', TO_NUMBER('091973', 18, 0), 'Internal Stream/CHANGES query error for ROW_ID: ''%1%''.', REGEXP_REPLACE(METADATA$ROW_ID, '~.{0,20}:([A-Za-z0-9+\\\\/=]{20,})', '~[OBFVAL]:\\\\1', 1, 0, 'c')), 18, 5))) > (0), 'INSERT', 'DELETE')) = 'INSERT'"
}
